"""Bind an explicit crossing-to-free candidate to original native identities.

This opt-in construction is not part of separator dispatch yet. A semantic
planner must first prove the original Bundle and its unique continuation.
The boundary side comes from consecutive ports in the original incidence
ring, never from a nearest road or a guessed coordinate direction. No profile
is changed, and the binding does not claim a generated or complete separator.
"""
from numbers import Integral

from .curved_separator_chain_bindings import _rows, _unique
from .curved_free_chain_bindings import COLUMNS as FREE_COLUMNS

COLUMNS = dict(FREE_COLUMNS)
COLUMNS['Approaches'] += ('st_cj_order', 'st_cj_half')


def resolve(item, columns, owners):
    tables = {key: _rows(columns[key], names) for key, names in COLUMNS.items()}
    mapping, corridors, external, mouths = (tables[key] for key in COLUMNS)
    spans = _unique((r[:3] for r in mapping), 'original span')
    ports = _unique((r[:3] for r in mouths), 'original endpoint')
    strips = _unique((r[0] for r in corridors), 'corridor span')
    free = _unique((r[0] for r in external), 'external approach span')
    if set(strips) & set(free):
        raise ValueError('An original route cannot have two generated owners')
    if any(len(v) != 2 for v in (item.original_member_street_ids, item.boundary_street_ids,
            item.boundary_span_ids, item.attached_sites, item.attached_ends, item.free_ends, item.crossing_ends)):
        raise ValueError('Continuation region needs two exact original boundary sides')
    if (type(item.continuing_member_side) is not int or item.continuing_member_side not in (0, 1)
            or len(set(item.original_member_street_ids)) != 2 or len(set(item.boundary_street_ids)) != 2):
        raise ValueError('Continuation needs distinct original members and a recorded continuing side')
    side = item.continuing_member_side; other = 1-side
    if (item.boundary_street_ids[side] != item.original_member_street_ids[side]
            or item.boundary_street_ids[other] in (*item.original_member_street_ids, item.crossing_span_id[0])):
        raise ValueError('Only the finished member may acquire a separate continuation Street')
    if (len(set(owners.values())) != len(owners) or any(isinstance(v, bool) or not isinstance(v, Integral)
            or not 0 <= v < 2**20 for v in owners.values())):
        raise ValueError('Native patch owners must be distinct bounded integer indices')
    sites_seen = set()
    for sites in owners:
        if not sites or len(set(sites)) != len(sites) or sites_seen.intersection(sites):
            raise ValueError('Original junctions must have unique surface owners')
        sites_seen.update(sites)
    # This initial continuation branch uses two ordinary physical junctions.
    # A compound cap needs additional incidence/coverage rules of its own.
    if (any(len(s) != 1 or s not in owners for s in item.attached_sites)
            or item.attached_sites[0] == item.attached_sites[1]):
        raise ValueError('Continuation cap needs two distinct original physical owners')

    def key(end): return (end.street_id, end.section_id, end.end)
    def port(end, sites):
        identity = key(end)
        if identity not in ports or mouths[ports[identity]][3] not in sites:
            raise ValueError('A cap endpoint left its exact original junction')
        return ports[identity]

    identity = item.crossing_span_id
    if identity not in spans or spans[identity] not in strips:
        raise ValueError('Continuation lost its original crossing corridor')
    cross = strips[spans[identity]]; row = corridors[cross]
    if (row[1] != identity[0] or mapping[row[0]][3:] != (0, 0)
            or any(not 0 <= p < len(mouths) for p in row[2:])
            or mouths[row[2]][:3] != (identity[0], identity[1], 0)
            or mouths[row[3]][:3] != (identity[0], identity[2], 1)):
        raise ValueError('Crossing registry changed its original Street or Section endpoints')
    crossing_ports = tuple(port(end, sites) for end, sites in zip(item.crossing_ends, item.attached_sites))
    if set(crossing_ports) != set(row[2:]) or len(set(crossing_ports)) != 2:
        raise ValueError('Crossing must connect both exact attached owners')

    record = dict(bundle_id=item.bundle_id, member_a=item.boundary_street_ids[0],
                  member_b=item.boundary_street_ids[1], crossing_corridor=cross,
                  crossing_street=identity[0])
    rules = []
    for at, sid in enumerate(item.boundary_street_ids):
        identity = item.boundary_span_ids[at]
        if identity[0] != sid or identity not in spans or spans[identity] not in free:
            raise ValueError('Continuation side lost its exact original free approach')
        span = spans[identity]; approach = free[span]; actual = external[approach]
        attached = port(item.attached_ends[at], item.attached_sites[at])
        reverse = mouths[attached][2]
        if (actual[1:3] != (sid, attached) or actual[3:] != (1, -1, -1)
                or reverse not in (0, 1) or key(item.attached_ends[at]) !=
                    (sid, identity[2] if reverse else identity[1], reverse)
                or key(item.free_ends[at]) != (sid, identity[1] if reverse else identity[2], 1-reverse)
                or key(item.free_ends[at]) in ports
                or mapping[span][3:] != ((1, 0) if reverse else (0, 1))):
            raise ValueError('Boundary approach must preserve its exact attached and genuine free ends')
        if at == other:
            generated = {r[0] for r in (*corridors, *external) if r[1] == sid}
            if generated != {span}:
                raise ValueError('The new continuation must consume its complete original route')
        junction = mouths[attached][3]
        ring = [r for r in mouths if r[3] == junction]
        if len(ring) < 3 or sorted(r[4] for r in ring) != list(range(len(ring))):
            raise ValueError('Original junction ring must have a complete unambiguous order')
        delta = (mouths[crossing_ports[at]][4]-mouths[attached][4]) % len(ring)
        if delta not in (1, len(ring)-1):
            raise ValueError('An intervening original port occupies the proposed separator cap')
        inner_side = -1 if delta == 1 else 1
        if mouths[attached][5] not in (0, inner_side):
            raise ValueError('The existing half-profile faces away from the proposed separator')
        prefix = 'a_' if at == 0 else 'b_'
        record.update({prefix+'attached': attached, prefix+'external': approach,
                       prefix+'inner_side': inner_side, prefix+'crossing': crossing_ports[at],
                       prefix+'patch': owners[item.attached_sites[at]]})
        rules.append((at, 3, approach))
        rules.append((2, 0, owners[item.attached_sites[at]]))
    rules.append((2, 1, cross))
    return record, tuple(rules)


def bind(preparation, tables, label, *, original_bundle_ids):
    """Author separate continuation tables; established separator rows stay exact."""
    from dataclasses import asdict
    from types import SimpleNamespace
    from .curved_junction_bindings import _mesh
    from .curved_patch_provider_bindings import values,owner_sites
    from .curved_separator_region_identity import RegionNamespaces
    sites=values(tables['Junctions'],'st_cj_junction_id')
    owners={tuple(sorted(sites[i] for i in group)):int(owner) for owner,group in
            owner_sites({k:SimpleNamespace(data=v) for k,v in tables.items()}).items()}
    columns={key:{name:values(tables[key],name) for name in names} for key,names in COLUMNS.items()}
    items=[asdict(item) for item in preparation.regions]
    namespaces=RegionNamespaces.allocate(original_bundle_ids,
        [int(v) for v in values(tables['Separators'],'st_sb_bundle_id')],items)
    rows=[];rules=[];metadata=[]
    for item,identity in zip(preparation.regions,items):
        row,allowed=resolve(item,columns,owners)
        row.update(kind=5,region_id=namespaces.continuation(identity),
                   original_a=item.original_member_street_ids[0],original_b=item.original_member_street_ids[1],
                   continuing_side=item.continuing_member_side)
        rows.append(row)
        rules.extend((row['region_id'],item.bundle_id,*permission) for permission in allowed)
        metadata.append(dict(identity,region_id=row['region_id']))
    # Explicit schemas also exist for empty components.
    names=('kind','region_id','bundle_id','original_a','original_b','continuing_side',
           'member_a','member_b','crossing_corridor','crossing_street',
           'a_attached','a_external','a_inner_side','a_crossing','a_patch',
           'b_attached','b_external','b_inner_side','b_crossing','b_patch')
    declarations=_mesh(label+' private continuation regions',[(0.,0.,0.)]*len(rows),[],[
        ('st_sb_'+key,'INT','POINT',[row[key] for row in rows]) for key in names])
    permissions=_mesh(label+' private continuation owners',[(0.,0.,0.)]*len(rules),[],[
        ('st_sr_'+key,'INT','POINT',[row[i] for row in rules])
        for i,key in enumerate(('region_id','bundle_id','role','kind','owner'))])
    return declarations,permissions,metadata
